package com.cgengine.model;
import com.cgengine.math.*;
import java.util.List;
public final class ModelValidator {private ModelValidator(){} public static void validate(Model m){if(m==null)throw new ModelValidationException("Model is null");for(Vector3f v:m.vertices)if(v==null||!VectorMath.isFinite(v))throw new ModelValidationException("Invalid vertex");for(Vector2f v:m.textureVertices)if(v==null||!Float.isFinite(v.x())||!Float.isFinite(v.y()))throw new ModelValidationException("Invalid texture coordinate");for(Vector3f v:m.normals)if(v==null||!VectorMath.isFinite(v))throw new ModelValidationException("Invalid normal");for(Polygon p:m.polygons){if(p==null||p.getVertexIndices().size()!=3)throw new ModelValidationException("Face must contain exactly three vertices");indexes(p.getVertexIndices(),m.vertices.size());optional(p.getTextureVertexIndices(),m.textureVertices.size());optional(p.getNormalIndices(),m.normals.size());}}private static void optional(List<Integer> i,int n){if(!i.isEmpty()){if(i.size()!=3)throw new ModelValidationException("Incomplete indices");indexes(i,n);}}private static void indexes(List<Integer> i,int n){for(Integer v:i)if(v==null||v<0||v>=n)throw new ModelValidationException("Invalid index");}}
